interface RawRecord {
  first_name: string;
  last_name: string;
  email_address: string;
  phone_number?: string;
  signup_date: string;
  total_purchases: string;
  is_active: string;
}

interface TransformedRecord {
  fullName: string;
  email: string;
  phone: string | null;
  signupDate: string;
  totalPurchases: number;
  isActive: boolean;
  tier: 'bronze' | 'silver' | 'gold' | 'platinum';
}

interface TransformResult {
  records: TransformedRecord[];
  stats: { total: number; active: number; avgPurchases: number; byTier: Record<string, number> };
}

function classifyTier(purchases: number): 'bronze' | 'silver' | 'gold' | 'platinum' {
  if (purchases >= 100) return 'platinum';
  if (purchases >= 50) return 'gold';
  if (purchases >= 10) return 'silver';
  return 'bronze';
}

function main(req: { body: string }): TransformResult | { error: string } {
  const body = jsonParse(req.body, {} as any);
  const raw: RawRecord[] = body.records || [];

  if (!Array.isArray(raw) || raw.length === 0) {
    return { error: 'provide records array in body' };
  }

  const records: TransformedRecord[] = raw.map((r: RawRecord) => {
    const purchases = parseInt(r.total_purchases) || 0;
    return {
      fullName: `${(r.first_name || '').trim()} ${(r.last_name || '').trim()}`.trim(),
      email: (r.email_address || '').toLowerCase().trim(),
      phone: r.phone_number ? r.phone_number.replace(/[^0-9+]/g, '') : null,
      signupDate: new Date(r.signup_date).toISOString().split('T')[0],
      totalPurchases: purchases,
      isActive: r.is_active === 'true' || r.is_active === '1',
      tier: classifyTier(purchases)
    };
  });

  const active = records.filter(r => r.isActive).length;
  const totalPurchases = records.reduce((sum, r) => sum + r.totalPurchases, 0);
  const byTier: Record<string, number> = {};
  records.forEach(r => { byTier[r.tier] = (byTier[r.tier] || 0) + 1; });

  return {
    records,
    stats: {
      total: records.length,
      active,
      avgPurchases: Math.round(totalPurchases / records.length),
      byTier
    }
  };
}
